parameters.description:
Search for tourist attractions or restaurants near a travel destination. 
Input must be a JSON string with two fields: 
{"location": "city or place name", "category": "attractions or restaurants"}
Example: {"location": "Cox's Bazar", "category": "attractions"}

parameters.jsCode:
const location = query.location;
const category = query.category; // "attractions" অথবা "restaurants"
const apiKey = "YOUR_GEOAPIFY_API_KEY";

// ধাপ ১: Geocoding - location name থেকে lat/lon বের করা
const geoUrl = `https://api.geoapify.com/v1/geocode/search?text=${encodeURIComponent(location)}&apiKey=${apiKey}`;
const geoResponse = await this.helpers.httpRequest({
  method: 'GET',
  url: geoUrl,
  json: true
});

if (!geoResponse.features || geoResponse.features.length === 0) {
  return `"${location}" এর জন্য কোনো কোঅর্ডিনেট পাওয়া যায়নি।`;
}

const [lon, lat] = geoResponse.features[0].geometry.coordinates;

// ধাপ ২: Category ম্যাপ করা
const categoryMap = {
  attractions: 'tourism.sights',
  restaurants: 'catering.restaurant'
};
const geoapifyCategory = categoryMap[category] || 'tourism.sights';

// ধাপ ৩: Places search
const placesUrl = `https://api.geoapify.com/v2/places?categories=${geoapifyCategory}&filter=circle:${lon},${lat},5000&limit=10&apiKey=${apiKey}`;
const placesResponse = await this.helpers.httpRequest({
  method: 'GET',
  url: placesUrl,
  json: true
});

if (!placesResponse.features || placesResponse.features.length === 0) {
  return `${location}-এ কোনো ${category} পাওয়া যায়নি।`;
}

// শুধু দরকারি তথ্য বের করে সংক্ষিপ্ত ফলাফল রিটার্ন করা
const results = placesResponse.features.map(f => ({
  name: f.properties.name || "নাম নেই",
  address: f.properties.formatted || "",
  category: f.properties.categories ? f.properties.categories[0] : ""
}));

return JSON.stringify(results);

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "location": {
      "type": "string",
      "description": "City or place name, e.g. Cox's Bazar"
    },
    "category": {
      "type": "string",
      "description": "Either 'attractions' or 'restaurants'"
    }
  },
  "required": ["location", "category"]
}
